export const atelierUpdateContactDispositionResponseInfluenceScoreMax = 5;

export const atelierUpdateContactDispositionResponseRelationshipStrengthMin = 0;
export const atelierUpdateContactDispositionResponseRelationshipStrengthMax = 100;

export const atelierUpdateContactDispositionResponseRelationshipTrendItemStrengthMin = 0;
export const atelierUpdateContactDispositionResponseRelationshipTrendItemStrengthMax = 100;

export const AtelierUpdateContactDispositionResponse = zod.object({
  id: zod.string(),
  accountId: zod.string(),
  fullName: zod.string(),
  personId: zod.string().nullish(),
  honorific: zod.string().nullish(),
  firstName: zod.string().nullish(),
  middleName: zod.string().nullish(),
  lastName: zod.string().nullish(),
  preferredName: zod.string().nullish(),
  displayName: zod.string().nullish(),
  title: zod.string().nullish(),
  seniority: zod
    .union([
      zod.literal("board_chair"),
      zod.literal("board_member"),
      zod.literal("c_suite"),
      zod.literal("vp"),
      zod.literal("director"),
      zod.literal("manager"),
      zod.literal("ic"),
      zod.literal("unknown"),
      zod.literal(null),
    ])
    .nullish(),
  email: zod.string().nullish(),
  phone: zod.string().nullish(),
  linkedinUrl: zod.string().nullish(),
  buyerPersona: zod.string().nullish(),
  criticalRole: zod
    .union([
      zod.literal("ceo"),
      zod.literal("cfo"),
      zod.literal("coo"),
      zod.literal("caio"),
      zod.literal("cto"),
      zod.literal("cio"),
      zod.literal("cdo"),
      zod.literal("head_of_ai"),
      zod.literal("cmo"),
      zod.literal("cpo_product"),
      zod.literal("cco_commercial"),
      zod.literal("cpo_procurement"),
      zod.literal("head_of_transformation"),
      zod.literal("head_of_pmo"),
      zod.literal("head_of_vro"),
      zod.literal(null),
    ])
    .nullish(),
  entityName: zod.string().nullish(),
  entityScope: zod
    .union([
      zod.literal("parent_group"),
      zod.literal("subsidiary"),
      zod.literal("division"),
      zod.literal("standalone"),
      zod.literal(null),
    ])
    .nullish(),
  influenceScore: zod
    .number()
    .min(1)
    .max(atelierUpdateContactDispositionResponseInfluenceScoreMax),
  disposition: zod.enum([
    "champion",
    "supporter",
    "neutral",
    "skeptic",
    "blocker",
    "unknown",
  ]),
  lastContactAt: zod.string().nullish(),
  contactOwnerId: zod.string().nullish(),
  contactOwnerName: zod.string().nullish(),
  relationshipStrength: zod
    .number()
    .min(atelierUpdateContactDispositionResponseRelationshipStrengthMin)
    .max(atelierUpdateContactDispositionResponseRelationshipStrengthMax)
    .optional(),
  nextTouchAt: zod.string().nullish(),
  relationshipTrend: zod
    .array(
      zod.object({
        at: zod.string().describe("ISO timestamp of the snapshot."),
        strength: zod
          .number()
          .min(
            atelierUpdateContactDispositionResponseRelationshipTrendItemStrengthMin,
          )
          .max(
            atelierUpdateContactDispositionResponseRelationshipTrendItemStrengthMax,
          ),
        disposition: zod.string().nullish(),
        note: zod.string().nullish(),
      }),
    )
    .optional(),
  notes: zod.string().nullish(),
  timeInRole: zod.string().nullish(),
  careerHistory: zod
    .array(
      zod.object({
        role: zod.string(),
        company: zod.string(),
        period: zod.string().nullish(),
        highlight: zod.string().nullish(),
      }),
    )
    .optional(),
  education: zod
    .array(
      zod.object({
        institution: zod.string(),
        programme: zod.string().nullish(),
        year: zod.string().nullish(),
      }),
    )
    .optional(),
  sourceUrl: zod.string().nullish(),
  confidence: zod
    .enum(["verified", "inferred"])
    .describe(
      '\"verified\" when at least one citation directly names the\nperson; \"inferred\" when the contact came from a heuristic\n(title pattern, org chart inference) without a direct cite.\n',
    ),
});

